import { defineConfig } from 'orval';

// The spec is generated by the backend (`make openapi` at the repo root).
const input = '../../api/openapi/swagger.json';

export default defineConfig({
	// TanStack Query hooks on top of the axios instance in api/axios-instance.ts.
	api: {
		input,
		output: {
			client: 'react-query',
			httpClient: 'axios',
			mode: 'tags-split',
			target: 'src/api/endpoints',
			schemas: 'src/api/model',
			clean: true,
			override: {
				mutator: {
					path: 'src/api/axios-instance.ts',
					name: 'customInstance',
				},
				operations: {
					// The QR is an image, and the Authorization header rules out an <img src>, so it is read
					// as a Blob and shown through an object URL.
					getLinkQr: {
						requestOptions: { responseType: 'blob' },
					},
					// The campaign export is a CSV file; it is saved through an object URL for the same reason.
					exportCampaign: {
						requestOptions: { responseType: 'blob' },
					},
				},
			},
		},
	},
	// Zod schemas of each request (params, body) and response, to validate forms before sending.
	zod: {
		input,
		output: {
			client: 'zod',
			mode: 'tags-split',
			target: 'src/api/zod',
			fileExtension: '.zod.ts',
			clean: true,
			override: {
				zod: { version: 4 },
			},
		},
	},
});
